.chapter-container {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #00CED1;
  --warm: #FFBF00;
  --line: #e0e0e0;
  --paper: #f9f9f9;
  font-family: 'Segoe UI', system-ui, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  line-height: 1.6;
}

.chapter-header {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1rem;
  margin-bottom: 2rem;
}

.chapter-title {
  font-size: 2rem;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
}

.chapter-lead {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 800px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.narrative-panel {
  background: #fff;
  padding: 1.5rem;
  border-left: 4px solid var(--accent);
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.section-heading {
  font-size: 1.4rem;
  margin-top: 0;
  color: var(--ink);
}

.narrative-panel p {
  font-size: 15px;
  margin-bottom: 1rem;
  text-align: justify;
}

.source-citation-block {
  margin-top: 1.5rem;
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.source-btn {
  background: var(--ink);
  color: #fff;
  border: none;
  padding: 0.4rem 0.8rem;
  font-size: 13px;
  cursor: pointer;
  border-radius: 3px;
  transition: opacity 0.2s;
}

.source-btn:hover {
  opacity: 0.8;
}

.visual-panel {
  background: #fff;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  max-width: 600px;
  margin-bottom: 1rem;
}

canvas {
  width: 100%;
  height: auto;
  background: #fff;
  border: 1px solid var(--line);
}

.canvas-controls {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: 100%;
  max-width: 600px;
  padding: 0.5rem;
  background: var(--paper);
  border-radius: 4px;
}

.canvas-controls label {
  font-size: 13px;
  color: var(--muted);
}

.canvas-controls input[type="range"] {
  width: 100%;
  cursor: pointer;
}

.legend-box {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: 13px;
  color: var(--muted);
  margin-top: 0.5rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.dot.dac { background: var(--warm); }
.dot.taylor { background: #ff6b6b; }
.dot.proposed { background: var(--accent); }

.line.crlb {
  width: 20px;
  height: 2px;
  background: var(--ink);
  display: inline-block;
}

.claims-section {
  background: #fff;
  padding: 1.5rem;
  border-top: 2px solid var(--line);
}

.claims-title {
  font-size: 1.2rem;
  margin-top: 0;
  color: var(--ink);
}

.claims-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.claim-item {
  padding: 1rem 0;
  border-bottom: 1px solid var(--line);
  font-size: 15px;
}

.claim-item:last-child {
  border-bottom: none;
}

.claim-conditions {
  font-size: 13px;
  color: var(--muted);
  margin: 0.3rem 0;
  font-style: italic;
}

