(function() {
  'use strict';

  const canvas = document.getElementById('problem-canvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const slider = document.getElementById('noise-slider');
  const noiseValueDisplay = document.getElementById('noise-value');
  const resetBtn = document.getElementById('reset-btn');

  if (!slider || !noiseValueDisplay || !resetBtn) return;

  const width = canvas.width;
  const height = canvas.height;
  const padding = { top: 40, right: 30, bottom: 50, left: 60 };
  const plotWidth = width - padding.left - padding.right;
  const plotHeight = height - padding.top - padding.bottom;

  const xMin = -5; 
  const xMax = -3; 
  const yMin = 0; 
  const yMax = 1000; 

  const dacThresholdLog = Math.log10(0.000016);
  const proposedThresholdLog = Math.log10(0.0001);

  function logToX(logVal) {
    return padding.left + ((logVal - xMin) / (xMax - xMin)) * plotWidth;
  }

  function mseToY(mse) {
    const clampedMse = Math.max(yMin, Math.min(yMax, mse));
    return padding.top + plotHeight - ((clampedMse - yMin) / (yMax - yMin)) * plotHeight;
  }

  function drawGrid() {
    ctx.strokeStyle = '#e0e0e0';
    ctx.lineWidth = 1;
    ctx.font = '12px sans-serif';
    ctx.fillStyle = '#666';
    ctx.textAlign = 'center';

    for (let i = 0; i <= 5; i++) {
      const xVal = xMin + (i * (xMax - xMin) / 5);
      const x = logToX(xVal);
      ctx.beginPath();
      ctx.moveTo(x, padding.top);
      ctx.lineTo(x, height - padding.bottom);
      ctx.stroke();
      ctx.fillText(xVal.toFixed(1), x, height - padding.bottom + 20);
    }

    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const yVal = yMin + (i * (yMax - yMin) / 5);
      const y = mseToY(yVal);
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();
      ctx.fillText(yVal.toFixed(0), padding.left - 10, y + 4);
    }

    ctx.fillStyle = '#1a1a1a';
    ctx.textAlign = 'center';
    ctx.fillText('log₁₀(σ²)', width / 2, height - 10);
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('MSE', 0, 0);
    ctx.restore();
  }

  function drawCRLB() {
    ctx.strokeStyle = '#1a1a1a';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    const yCRLB = mseToY(10);
    ctx.moveTo(padding.left, yCRLB);
    ctx.lineTo(width - padding.right, yCRLB);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#1a1a1a';
    ctx.textAlign = 'left';
    ctx.fillText('CRLB', padding.left + 5, yCRLB - 5);
  }

  function drawDAC(logSigmaSq) {
    ctx.strokeStyle = '#FFBF00';
    ctx.lineWidth = 3;
    ctx.beginPath();
    let started = false;
    for (let x = xMin; x <= xMax; x += 0.05) {
      let mse;
      if (x < dacThresholdLog) {
        mse = 10 * Math.pow(10, (x - xMin) * 0.5);
      } else {
        mse = 10 + Math.pow(10, (x - dacThresholdLog) * 3) * 50;
      }
      const plotX = logToX(x);
      const plotY = mseToY(mse);
      if (!started) {
        ctx.moveTo(plotX, plotY);
        started = true;
      } else {
        ctx.lineTo(plotX, plotY);
      }
    }
    ctx.stroke();
  }

  function drawTaylor(logSigmaSq) {
    ctx.strokeStyle = '#ff6b6b';
    ctx.lineWidth = 3;
    ctx.beginPath();
    let started = false;
    for (let x = xMin; x <= xMax; x += 0.05) {
      let mse = 10 * Math.pow(10, (x - xMin) * 0.6) * (1 + (x - xMin) * 0.2);
      const plotX = logToX(x);
      const plotY = mseToY(mse);
      if (!started) {
        ctx.moveTo(plotX, plotY);
        started = true;
      } else {
        ctx.lineTo(plotX, plotY);
      }
    }
    ctx.stroke();
  }

  function drawProposed(logSigmaSq) {
    ctx.strokeStyle = '#00CED1';
    ctx.lineWidth = 3;
    ctx.beginPath();
    let started = false;
    for (let x = xMin; x <= xMax; x += 0.05) {
      let mse;
      if (x < proposedThresholdLog) {
        mse = 10 * Math.pow(10, (x - xMin) * 0.55);
      } else {
        mse = 10 * Math.pow(10, (proposedThresholdLog - xMin) * 0.55) + Math.pow(10, (x - proposedThresholdLog) * 1.5) * 20;
      }
      const plotX = logToX(x);
      const plotY = mseToY(mse);
      if (!started) {
        ctx.moveTo(plotX, plotY);
        started = true;
      } else {
        ctx.lineTo(plotX, plotY);
      }
    }
    ctx.stroke();
  }

  function drawCurrentPoint(logSigmaSq) {
    const x = logToX(logSigmaSq);
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.arc(x, padding.top + plotHeight / 2, 5, 0, Math.PI * 2);
    ctx.fill();
  }

  function render() {
    ctx.clearRect(0, 0, width, height);
    drawGrid();
    drawCRLB();
    drawDAC();
    drawTaylor();
    drawProposed();
    const currentLogSigmaSq = parseFloat(slider.value);
    drawCurrentPoint(currentLogSigmaSq);
    const sigmaSq = Math.pow(10, currentLogSigmaSq);
    noiseValueDisplay.textContent = sigmaSq.toExponential(2);
  }

  slider.addEventListener('input', render);
  resetBtn.addEventListener('click', () => {
    slider.value = -4.8;
    render();
  });

  render();
})();
